    ctx.moveTo(-20, 44);
    ctx.lineTo(-31, 46);
    ctx.lineTo(-38, 56);
    ctx.lineTo(-37, 99);
    ctx.lineTo(-20, 99);
    ctx.lineTo(-20, 57);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = visual.ternoIluminado;
    ctx.beginPath();
    ctx.moveTo(-20, 48);
    ctx.lineTo(-29, 50);
    ctx.lineTo(-34, 59);
    ctx.lineTo(-33, 95);
    ctx.lineTo(-24, 95);
    ctx.lineTo(-23, 56);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = visual.contorno;
    ctx.beginPath();
    ctx.moveTo(20, 44);
    ctx.lineTo(31, 47);
    ctx.lineTo(38, 57);
    ctx.lineTo(35, 72);
    ctx.lineTo(25, 91);
    ctx.lineTo(13, 95);
    ctx.lineTo(8, 82);
    ctx.lineTo(20, 69);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = visual.ternoIluminado;
    ctx.beginPath();
    ctx.moveTo(21, 48);
