    ctx.lineTo(-8, 43);
    ctx.lineTo(-1, 73);
    ctx.lineTo(-17, 58);
    ctx.closePath();
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(18, 43);
    ctx.lineTo(8, 43);
    ctx.lineTo(1, 73);
    ctx.lineTo(17, 58);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = visual.gravata;
