    ctx.fillStyle = visual.camisa;
    ctx.fillRect(11, 86, 7, 7);
    ctx.fillStyle = visual.contorno;
    ctx.fillRect(9, 92, 20, 4);
    ctx.fillStyle = visual.ternoIluminado;
