        ctx.fillStyle = camada % 2 === 0 ? "#d9a552" : "#c89145";
        ctx.fillRect(posicaoX, posicaoY, largura, 10);
        ctx.fillStyle = "#a76a35";
        ctx.fillRect(posicaoX + Math.floor(largura * 0.68), posicaoY, Math.ceil(largura * 0.32), 10);
