    ctx.fillStyle = aparenciaDoAviso.fundo;
    desenharRetanguloArredondado(canvas.width / 2 - 190, canvas.height / 2 - 72, 380, 144, 22);
    ctx.fill();
    ctx.strokeStyle = aparenciaDoAviso.borda;
    ctx.lineWidth = 2;
